import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateSpaceContent } from "../handlers/updateSpaceContent";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { UpdateContentRequest } from "../types/UpdateContentRequest";

type Data = Awaited<ReturnType<typeof updateSpaceContent>>;
type Vars = { spacePk: SpacePartition; req: UpdateContentRequest };

export function useUpdateSpaceContent(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateSpaceContent(vars.spacePk, vars.req),
    ...options,
  });
}
